import{_ as t,o,c as r,a3 as a}from"./chunks/framework.CpLciM8b.js";const g=JSON.parse('{"title":"Threat Model","description":"","frontmatter":{},"headers":[],"relativePath":"reference/threat-model.md","filePath":"reference/threat-model.md","lastUpdated":1785494959000}'),n={name:"reference/threat-model.md"};function s(i,e,d,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="threat-model" tabindex="-1">Threat Model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat Model&quot;">​</a></h1><p>Security model for a self-hosted Flakemetry instance. Scope: the ingestion API, the dashboard, the processing worker, Postgres, and the object store. Companion to <a href="https://github.com/AKogut/flakemetry/blob/main/docs/architecture.md" target="_blank" rel="noreferrer">Architecture</a> and <a href="https://github.com/AKogut/flakemetry/blob/main/docs/configuration.md" target="_blank" rel="noreferrer">Configuration</a>.</p><h2 id="assets" tabindex="-1">Assets <a class="header-anchor" href="#assets" aria-label="Permalink to &quot;Assets&quot;">​</a></h2><ul><li><strong>Test intelligence data</strong> — runs, executions, error signatures, flaky scores, RCA reports. Tenant-scoped; disclosure across tenants is the primary confidentiality concern.</li><li><strong>Ingest tokens</strong> — per-project bearer secrets. Stored only as SHA-256 hashes; the raw value is shown once at creation.</li><li><strong>User sessions</strong> — Auth.js database sessions behind OAuth.</li><li><strong>Workspace invitations</strong> — bearer links granting membership. Stored only as SHA-256 hashes, shown once, single-use, seven-day expiry, revocable. Accepting deliberately does not require the signed-in address to match the invited one (GitHub emails are frequently private or absent); expiry, revocation and single use carry the weight instead.</li><li><strong>Artifacts</strong> — screenshots, video, traces, HAR files in the object store, addressed by tenant-scoped keys and served via short-lived signed URLs.</li><li><strong>LLM budget</strong> — per-project daily token cap; abuse is a cost/DoS concern.</li></ul><h2 id="trust-boundaries" tabindex="-1">Trust boundaries <a class="header-anchor" href="#trust-boundaries" aria-label="Permalink to &quot;Trust boundaries&quot;">​</a></h2><ol><li><strong>CI → Ingestion API.</strong> Untrusted payloads authenticated by an ingest token. The boundary that receives the most attacker-controllable input (error messages, stacks, file paths, CODEOWNERS, notification routing).</li><li><strong>Browser → Dashboard.</strong> User-authenticated (OAuth + database sessions), role-gated per membership.</li><li><strong>API/Worker → Postgres / object store.</strong> Trusted internal services; every query is tenant-scoped by <code>orgId</code> + <code>projectId</code>.</li><li><strong>Worker → external webhooks / SMTP / LLM.</strong> Outbound to third parties on operator-supplied or config-supplied targets.</li></ol><h2 id="stride" tabindex="-1">STRIDE <a class="header-anchor" href="#stride" aria-label="Permalink to &quot;STRIDE&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Threat</th><th>Mitigation</th></tr></thead><tbody><tr><td><strong>Spoofing</strong></td><td>Forged ingest requests</td><td>Bearer token, looked up by SHA-256 hash (no plaintext compare); unknown/revoked tokens rejected. Dashboard requires an authenticated session.</td></tr><tr><td><strong>Tampering</strong></td><td>Cross-tenant writes; malicious payloads</td><td>Every read/write is scoped by <code>orgId</code> + <code>projectId</code>; ingest is validated against zod contracts before enqueue. Migrations are additive.</td></tr><tr><td><strong>Repudiation</strong></td><td>Untraceable policy changes; an export or deletion nobody can account for</td><td>Policy changes are recorded with actor and timestamp; the <code>authorization</code> header is redacted in logs. Every export and every erasure writes an audit row naming the actor, which deliberately has no foreign key to the tenant so a deletion cannot take its own record with it.</td></tr><tr><td><strong>Information disclosure</strong></td><td>Reading another tenant&#39;s data or artifacts</td><td>Tenant scoping on all queries, <strong>proven rather than asserted</strong>: <code>packages/queries/src/__tests__/tenant-isolation.test.ts</code> seeds two structurally identical tenants and checks every project-scoped query for the other&#39;s ids, with a coverage guard that fails when a new query is added without one. Artifact keys are tenant-prefixed and served only through short-lived signed URLs. Auth cookies are <code>httpOnly</code> + <code>secure</code> (prod) + <code>sameSite</code>.</td></tr><tr><td><strong>Denial of service</strong></td><td>Request floods, oversized/compressed bodies, ReDoS, alert/LLM abuse</td><td>Per-token fixed-window rate limiting with <code>Retry-After</code>; queue-depth backpressure (<code>503</code>); an 8 MB body limit that also bounds the decompressed gzip stream, plus an explicit 16 MB decompression ceiling as defense-in-depth; the CODEOWNERS glob compiler collapses adjacent wildcards and caps pattern length/count; the notification dedupe window and per-project daily LLM token cap bound outbound cost.</td></tr><tr><td><strong>Elevation of privilege</strong></td><td>A viewer changing settings; a read credential becoming a write one; a CI token silencing a failing test</td><td>Owner/admin role checks on token, policy, notification and quarantine management; tenant deletion is owner-only and needs the slug typed, checked server-side. The bulk export omits ingest token hashes, webhook signing secrets and the badge token, so a <code>read</code> credential cannot be turned into one that writes. Quarantine has its own token scope: hiding a failing test is neither reading nor reporting, and the credential pasted into every CI job must not carry it.</td></tr></tbody></table><h2 id="attacker-controllable-input-and-how-it-is-contained" tabindex="-1">Attacker-controllable input, and how it is contained <a class="header-anchor" href="#attacker-controllable-input-and-how-it-is-contained" aria-label="Permalink to &quot;Attacker-controllable input, and how it is contained&quot;">​</a></h2><ul><li><strong>Error messages / stacks</strong> — scrubbed before storage; rendered as data, never evaluated. RCA prompts treat them as untrusted content.</li><li><strong>File paths / titles</strong> — flow into the PR-gate comment, which escapes backticks/pipes/newlines; the base-branch ref is charset-validated at the route.</li><li><strong>CODEOWNERS</strong> — compiled with a wildcard-collapsing, length/-count-capped matcher (no catastrophic backtracking).</li><li><strong>Notification targets</strong> — webhook URLs must be https and are blocked from loopback/private/link-local/metadata ranges; email targets are format-validated; outbound webhook calls carry a timeout.</li><li><strong>Post-sign-in destination</strong> — the <code>next</code> parameter on <code>/sign-in</code> is validated to a plain path on this origin; <code>//host</code> and <code>/\\host</code> are read as protocol-relative URLs by browsers and would turn the sign-in page into an open redirect wearing our domain.</li></ul><h2 id="transport-hardening" tabindex="-1">Transport hardening <a class="header-anchor" href="#transport-hardening" aria-label="Permalink to &quot;Transport hardening&quot;">​</a></h2><ul><li><strong>API</strong> responds with <code>X-Content-Type-Options: nosniff</code>, <code>X-Frame-Options: DENY</code>, <code>Referrer-Policy: no-referrer</code>, <code>Cross-Origin-Resource-Policy: same-origin</code>, <code>Cache-Control: no-store</code>, and HSTS in production.</li><li><strong>Dashboard</strong> sets a Content-Security-Policy (<code>frame-ancestors &#39;none&#39;</code>, <code>object-src &#39;none&#39;</code>, <code>base-uri &#39;self&#39;</code>), <code>X-Frame-Options</code>, <code>X-Content-Type-Options</code>, <code>Referrer-Policy</code>, <code>Permissions-Policy</code>, and HSTS in production.</li></ul><h2 id="residual-risks-follow-ups" tabindex="-1">Residual risks / follow-ups <a class="header-anchor" href="#residual-risks-follow-ups" aria-label="Permalink to &quot;Residual risks / follow-ups&quot;">​</a></h2><ul><li>The dashboard CSP still allows <code>&#39;unsafe-inline&#39;</code> scripts; a nonce-based strict CSP is a follow-up.</li><li>SSRF protection blocks address literals but does not defend against DNS-rebinding of a webhook host; resolve-and-pin is a follow-up.</li><li>No formal RBAC/SSO beyond owner/admin/member roles (tracked in #49).</li><li>Tenant isolation is enforced in the query layer and tested there; Postgres row-level security is <strong>not</strong> enabled, so a query written without a tenant filter would be caught by the test suite rather than refused by the database.</li><li>Load/soak testing and ingestion SLOs are tracked separately (#71).</li></ul>',14)])])}const p=t(n,[["render",s]]);export{g as __pageData,p as default};
